UPDATE public.places SET latitude=37.674, longitude=35.510, short_description='Yahyalı ilçesindeki Aladağlar çevresinde, yedi ayrı noktadan dökülen güçlü takım şelaleleri.', long_description='Kapuzbaşı Takım Şelaleleri, Kayseri’nin Yahyalı ilçesinde, Aladağlar çevresinde yer alır. Resmî il turizm kaynağı Kayseri’den güzergâhın uzun olduğunu ve yolun son bölümünde stabilize yol bulunduğunu belirttiğinden ziyaret öncesi yol koşulları kontrol edilmelidir.', source_url='https://kayseri.ktb.gov.tr/TR-55130/kapuzbasi-takim-selaleleri.html', verified=true, trust_score=96, content_review_status='source_backed', updated_at=now() WHERE city='Kayseri' AND slug='kapuzbasi-selaleleri';
UPDATE public.places SET short_description='Türkiye’nin farklı bölgelerindeki simge yapıların ölçekli maketlerini açık hava alanında bir araya getiren kültür ve gezi kompleksi.', long_description='Miniatürk, Beyoğlu Sütlüce’de yer alır; Türkiye’den ve tarihî coğrafyadan seçilmiş yapıların maketlerini, açık hava sergilerini ve ailelere yönelik alanları bir arada sunar.', source_url='https://miniaturk.com.tr/Home/Hakkimizda', verified=true, trust_score=94, content_review_status='source_backed', updated_at=now() WHERE city='İstanbul' AND slug='osm-node-1352425761';
